// Important Points about Node.js

console.log("===== Node.js Important Points =====");

// Server Side
console.log("1. Node.js is used for Server-Side Development.");

// JavaScript Runtime
console.log("2. Node.js allows JavaScript to run outside the browser.");

// APIs
console.log("3. Node.js is mainly used to build REST APIs.");

// Backend
console.log("4. Node.js handles requests from clients and sends responses.");

// Database
console.log("5. Node.js connects applications with databases like MongoDB and MySQL.");

// Asynchronous
console.log("6. Node.js uses Non-Blocking I/O, making it fast and efficient.");

// Common Uses
console.log("7. Used in Web Applications, Chat Apps, Streaming Apps, and REST APIs.");

console.log("===================================");
